import React, {
	useEffect,
	useState,
} from "react";

import "./CheckBox.css";

const CheckBox = ({ data, active, updSelect,colors }) => {


	let styleS =  colors ? colors :{
		"--base-ck-primary-color":"var(--hrm_palette-blue-purple)",
		"--base-ck-primary-backcolor":"#f1f1f1",
	}
	
    return (
        <div className="_dsplFlx main_chckbx "  style={{...styleS}}>
           {data?.map(option=>{
			   return(
				   <div key={option.id} className="item_chckbx " is-active={`${active===option.id}`} onClick={()=>updSelect(option.id)}>
					   {option.label}
				   </div>
			   )
		   })}
        </div>
    )
}


export default CheckBox;